        require(address(this).balance >= amount);
        c.sendMoney(address(this), amount, ""); if (__ESBMC_reverted()) return;
        require(address(c).balance >= _value);
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;
        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
