import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.sendMoney(address(this), amount, "") {} catch { return; }
        vm.assume(address(c).balance >= _value);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.depositsCount() == countBefore && balanceBefore - address(c).balance == _value);
    }

    function testFuzz_run(uint256 amount, uint256 _value) public {
        _run(amount, _value);
    }

    receive() external payable {}
